CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS providers(id TEXT PRIMARY KEY,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agents(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,provider_id TEXT NOT NULL REFERENCES providers(id) ON DELETE RESTRICT,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workflows(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT,session_id TEXT REFERENCES sessions(id) ON DELETE RESTRICT,workflow_id TEXT REFERENCES workflows(id) ON DELETE RESTRICT,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workflow_nodes(id TEXT PRIMARY KEY,workflow_id TEXT NOT NULL REFERENCES workflows(id) ON DELETE CASCADE,task_id TEXT REFERENCES tasks(id) ON DELETE RESTRICT,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS task_dependencies(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,depends_on_task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE RESTRICT,data TEXT NOT NULL,UNIQUE(task_id,depends_on_task_id));
CREATE TABLE IF NOT EXISTS execution_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,task_id TEXT REFERENCES tasks(id) ON DELETE RESTRICT,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS artifacts(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,task_id TEXT REFERENCES tasks(id) ON DELETE RESTRICT,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS usage_records(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE RESTRICT,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS context_entries(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,task_id TEXT REFERENCES tasks(id) ON DELETE RESTRICT,data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS agents_project_idx ON agents(project_id);
CREATE INDEX IF NOT EXISTS sessions_agent_idx ON sessions(agent_id);
CREATE INDEX IF NOT EXISTS tasks_project_idx ON tasks(project_id);
CREATE INDEX IF NOT EXISTS tasks_session_idx ON tasks(session_id);
CREATE INDEX IF NOT EXISTS tasks_workflow_idx ON tasks(workflow_id);
CREATE INDEX IF NOT EXISTS events_task_idx ON execution_events(task_id,seq);
CREATE INDEX IF NOT EXISTS dependencies_task_idx ON task_dependencies(task_id);
CREATE INDEX IF NOT EXISTS contexts_project_idx ON context_entries(project_id);
CREATE INDEX IF NOT EXISTS tasks_status_idx ON tasks(json_extract(data,'$.status'));
